lessons.solution:
func Clamp(n, low, high int) int {
	if n < low {
		return low
	}
	if n > high {
		return high
	}
	return n
}

func SafeDivide(n, d int) (int, bool) {
	if d == 0 {
		return 0, false
	}
	return n / d, true
}

func SumTo(n int) int {
	total := 0
	for i := 1; i <= n; i++ {
		total += i
	}
	return total
}

func Digits(n int) int {
	if n == 0 {
		return 1
	}
	count := 0
	for n > 0 {
		count++
		n /= 10
	}
	return count
}

func GCD(a, b int) int {
	for b != 0 {
		a, b = b, a%b
	}
	return a
}

func DigitSum(n int) int {
	total := 0
	for n > 0 {
		total += n % 10
		n /= 10
	}
	return total
}

func EvenCount(values []int) int {
	count := 0
	for _, n := range values {
		if n%2 == 0 {
			count++
		}
	}
	return count
}

