lessons.solution:
func Balanced(s string) bool {
	depth := 0
	for _, r := range s {
		if r == '(' {
			depth++
		} else {
			depth--
		}
		if depth < 0 {
			return false
		}
	}
	return depth == 0
}

func HasDuplicate(values []int) bool {
	seen := map[int]bool{}
	for _, n := range values {
		if seen[n] {
			return true
		}
		seen[n] = true
	}
	return false
}

