}

lessons.solution:
func Anagram(a, b string) bool {
	counts := map[rune]int{}
	for _, r := range a {
		counts[r]++
	}
	for _, r := range b {
		counts[r]--
	}
	for _, count := range counts {
		if count != 0 {
			return false
		}
	}
	return true
}

