}

lessons.solution:
func BinaryContains(values []int, target int) bool {
	low, high := 0, len(values)-1
	for low <= high {
		mid := low + (high-low)/2
		if values[mid] == target {
			return true
		}
		if values[mid] < target {
			low = mid + 1
		} else {
			high = mid - 1
		}
	}
	return false
}
